        for c, value in enumerate(row):
            if value:
                positions.setdefault(value, []).append((r, c))
    anchor_row = min(r for r, _ in positions[8])
    for color, cells in positions.items():
        shift = min(r for r, _ in cells) - anchor_row
        for r, c in cells:
